begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,is_anonymous) values
('b1000000-0000-4000-8000-000000000001','owner-b@example.test',false),
('b1000000-0000-4000-8000-000000000002','buyer-b@example.test',false);
insert into public.admins values('b1000000-0000-4000-8000-000000000001','owner');
update public.payment_settings set enabled=true,upi_id='test@upi',payee_name='Test',activation_mode='instant';
create temporary table orders_test(kind text primary key,id uuid,reference text);
grant all on orders_test to authenticated;
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
insert into orders_test select 'first',(x->>'id')::uuid,x->>'reference' from (select public.create_payment_order((select id from public.plans where code='trial')) x) q;
select is((select amount_paise from public.payment_orders where id=(select id from orders_test where kind='first')),4900::bigint,'Amount comes from plan');
select is((select status from public.payment_orders where id=(select id from orders_test where kind='first')),'pending','New order is initiated');
select is((public.create_payment_order((select id from public.plans where code='trial'))->>'id')::uuid,(select id from orders_test where kind='first'),'Same open order reused');
select is(public.report_payment_result((select id from orders_test where kind='first'),'STATUS=SUCCESS;txnREF=WRONG;ApprovalRefNo=VALID0001'),'pending','Wrong reference pending');
select is((select reason from public.payment_orders where id=(select id from orders_test where kind='first')),'reference mismatch','Reference reason exact');
select is(public.report_payment_result((select id from orders_test where kind='first'),''),'pending','No response stays initiated');
select is(public.report_payment_result((select id from orders_test where kind='first'),'Status=SUCCESS&txnId=bad'),'pending','Invalid transaction ID pending');
select is((select reason from public.payment_orders where id=(select id from orders_test where kind='first')),'missing transaction id','Missing reason exact');
select is(public.report_payment_result((select id from orders_test where kind='first'),'STATUS=SUCCESS;txnREF='||(select reference from orders_test where kind='first')||';ApprovalRefNo=VALID0001'),'paid','Case-insensitive semicolon SUCCESS activates');
select is(public.is_premium_user(),true,'Instant activation grants premium');
select is((select ads_access_status::text from public.profiles where id=auth.uid()),'pending','Organic buyer enters approvals');
select is(public.report_payment_result((select id from orders_test where kind='first'),'Status=SUCCESS&txnId=VALID0001'),'paid','Repeated report idempotent');
select is((select count(*) from public.subscriptions where order_id=(select id from orders_test where kind='first')),1::bigint,'Only one subscription');
insert into orders_test select 'second',(x->>'id')::uuid,x->>'reference' from (select public.create_payment_order((select id from public.plans where code='trial')) x) q;
select is(public.report_payment_result((select id from orders_test where kind='second'),'Status=SUCCESS&txnId=VALID0002'),'paid','Second instant activation');
insert into orders_test select 'third',(x->>'id')::uuid,x->>'reference' from (select public.create_payment_order((select id from public.plans where code='trial')) x) q;
select is(public.report_payment_result((select id from orders_test where kind='third'),'Status=SUCCESS&txnId=VALID0003'),'paid','Third instant activation');
insert into orders_test select 'fourth',(x->>'id')::uuid,x->>'reference' from (select public.create_payment_order((select id from public.plans where code='trial')) x) q;
select is(public.report_payment_result((select id from orders_test where kind='fourth'),'Status=SUCCESS&txnId=VALID0004'),'review','Fourth requires manual review');
select is((select reason from public.payment_orders where id=(select id from orders_test where kind='fourth')),'automatic activation limit reached','Rate limit reason');
select throws_ok($$update public.payment_orders set status='paid'$$,'42501',null,'Client cannot update orders');
select throws_ok($$update public.subscriptions set ends_at=now()+interval '1 year'$$,'42501',null,'Client cannot update subscriptions');
select throws_ok($$select private.activate_payment((select id from orders_test where kind='fourth'),1,'VALID0004','upi_app')$$,'42501',null,'Internal activation inaccessible');
reset role;
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is(public.admin_payments_to_verify(),3::bigint,'Dashboard counts auto payments to verify today');
select public.admin_revoke_payment((select id from orders_test where kind='first'),'Bank transfer missing');
select ok((select revoked_at is not null from public.subscriptions where order_id=(select id from orders_test where kind='first')),'Revoke ends subscription entitlement');
select is((select status from public.payment_orders where id=(select id from orders_test where kind='first')),'revoked','Revocation recorded');
select public.admin_confirm_bank_payment((select id from orders_test where kind='second'));
select is(public.admin_payments_to_verify(),1::bigint,'Bank confirmation clears outstanding flag');
reset role;
select is((select count(*) from private.used_payment_utrs where utr='VALID0001'),1::bigint,'Revoked UTR remains blocked forever');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is(public.report_payment_result((select id from orders_test where kind='fourth'),'Status=SUCCESS&txnId=valid0001'),'pending','Revoked UTR reuse rejected case-insensitively');
select is((select reason from public.payment_orders where id=(select id from orders_test where kind='fourth')),'transaction id already used','Reused UTR reason exact');
reset role;
update public.payment_settings set activation_mode='manual';
set local role authenticated;
select is(public.report_payment_result((select id from orders_test where kind='fourth'),'Status=SUCCESS&txnId=VALID0004'),'review','Manual mode never client activates');
select is((select reason from public.payment_orders where id=(select id from orders_test where kind='fourth')),'awaiting bank verification by owner','Manual reason exact');
reset role;
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.admin_mark_payment_paid((select id from orders_test where kind='fourth'),'123456780004')$$,'Owner can activate manually');
reset role;
update public.payment_settings set activation_mode='instant';
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
insert into orders_test select 'late',(x->>'id')::uuid,x->>'reference' from (select public.create_payment_order((select id from public.plans where code='trial')) x) q;
reset role;
update public.payment_orders set created_at=now()-interval '3 hours' where id=(select id from orders_test where kind='late');
set local role authenticated;
select is(public.report_payment_result((select id from orders_test where kind='late'),'Status=SUCCESS&txnId=VALID0005'),'pending','Old SUCCESS pending');
select is((select reason from public.payment_orders where id=(select id from orders_test where kind='late')),'order older than 2 hours','Old order reason exact');
select is(public.report_payment_result((select id from orders_test where kind='late'),'Status=FAILURE'),'failed','Failure marked failed');
reset role;
update public.payment_settings set enabled=false;
set local role authenticated;
select throws_ok($$select public.create_payment_order((select id from public.plans where code='trial'))$$,'P0001','Payments are not available right now','Disabled settings block orders');
reset role;
update public.payment_orders set status='pending',created_at=now()-interval '25 hours' where id=(select id from orders_test where kind='late');
select private.cancel_stale_payment_orders();
select is((select status from public.payment_orders where id=(select id from orders_test where kind='late')),'cancelled','Cron cancels stale initiated orders');
select is((select count(*) from public.payment_events where kind='client_report'),12::bigint,'Every report has an audit event');
select * from finish();
rollback;
